organism GHZ {
  meta { author: "Devin Phillip Davis", purpose: "GHZ state generation" }

  gene ghz_state() on a, b, c {
    helix a;
    helix b;
    helix c;
    bond a, b;
    bond b, c;
    bond c, a;
    cleave a -> ca;
    cleave b -> cb;
    cleave c -> cc;
  }

  genome {
    ghz_state() @ [0, 1, 2];
  }
}
